SELECT n.name, mi1.info, MIN(non_leaf_1316.t_production_year), MAX(non_leaf_1316.t_production_year)
FROM title as t, kind_type as kt, movie_info as mi1, info_type as it1, cast_info as ci, role_type as rt, name as n, non_leaf_1316
WHERE (mi1.info IN ('Danish','Denmark','Mono','Sweden','USA')) AND (kt.kind IN ('episode','movie','tv movie')) AND (it1.id IN ('4','6','8')) AND (n.name ILIKE '%bodi%') AND it1.id = non_leaf_1316.mi1_info_type_id AND (rt.role IN ('actor','actress','cinematographer','costume designer'));